using AAXWarehouseTools.Feature.FnO;
using Microsoft.Dynamics.ApplicationPlatform.Environment;

/// <summary>
/// Reports the AAXWarehouseTools installation to the AtomicAx feature service, validates the signed
/// token it returns, and writes the outcome to the Infolog. Enqueued on the batch server at AOS startup
/// by <c>AAXWarehouseToolsFeatureEnsureHandler</c> and also available as a batch task. Persists nothing
/// and never throws to its caller.
/// </summary>
public class AAXWarehouseToolsFeatureEnsure extends RunBaseBatch
{
    #define.CurrentVersion(1)

    // Product configuration is defined in the AAXWarehouseToolsFeature macro library
    #macrolib.AAXWarehouseToolsFeature

}

Method.Source:
/// <summary>
/// Collects the environment identity of the running AOS, builds the request in the supporting
/// assembly, calls the feature service, validates the returned token, and writes the outcome to
/// the Infolog. Any CLR or X++ error is logged as a warning and swallowed.
/// </summary>
public static void ensureFeature()
{
    str tenantId;
    str hostUrl;
    str lcsEnvId;
    str platformVer;
    str productVer;
    str envName;
    str hosting;
    str environmentType;
    str body;
    str token;
    FeatureResult lr;

    try
    {
        // Collect the environment identity from the running AOS
        IApplicationEnvironment env = EnvironmentFactory::GetApplicationEnvironment();
        if (env)
        {
            tenantId    = env.get_Aad().get_TenantDomainGUID();
            hostUrl     = env.get_Infrastructure().get_HostUrl();
            platformVer = env.get_Infrastructure().get_BuildVersion();
            lcsEnvId    = env.get_LCS().get_LCSEnvironmentId();
        }

        // The application version is descriptive only
        try
        {
            productVer = Microsoft.Dynamics.BusinessPlatform.ProductInformation.Provider.ProductInfoProvider::get_Provider().get_ApplicationVersion();
        }
        catch (Exception::CLRError)
        {
            productVer = '';
        }

        envName = hostUrl ? hostUrl : lcsEnvId;

        // Resolve hosting and environment type from the running platform
        hosting         = AAXWarehouseToolsFeatureEnsure::resolveHosting(env);
        environmentType = AAXWarehouseToolsFeatureEnsure::resolveEnvironmentType(env);

        // Build the request payload in the supporting assembly
        body = FeatureClient::BuildEnvironmentRequest(
            #ProductId, '',
            tenantId, '', hostUrl,
            lcsEnvId, '', envName,
            environmentType, hosting,
            productVer, platformVer);

        // Validate the install and register it if the service does not know it yet
        token = FeatureClient::PhoneHome(#ApiBaseUrl, #RouteValidate, body, #SubscriptionKey, #TimeoutMs);
        if (!token)
        {
            token = FeatureClient::PhoneHome(#ApiBaseUrl, #RouteRegister, body, #SubscriptionKey, #TimeoutMs);
        }

        if (!token)
        {
            warning(strFmt("AAXWarehouseTools: feature ensure for '%1' could not reach the service (offline or not yet deployed).", #ProductId));
            return;
        }

        // Verify the token signature and evaluate the result offline
        lr = FeatureClient::Validate(token, '');
        info(strFmt("AAXWarehouseTools: feature '%1' ensured - state %2, allowed %3.",
            #ProductId, lr.get_State(), lr.get_Allowed()));
    }
    catch (Exception::CLRError)
    {
        warning(strFmt("AAXWarehouseTools: feature ensure for '%1' failed (CLR error) - continuing.", #ProductId));
    }
    catch (Exception::Error)
    {
        warning(strFmt("AAXWarehouseTools: feature ensure for '%1' failed - continuing.", #ProductId));
    }
}

/// <summary>
/// Resolves the hosting value reported to the feature service from the running environment.
/// Uses the platform hosting environment first and falls back to the deployment type.
/// </summary>
/// <param name = "_env">The application environment of the running AOS.</param>
/// <returns>Cloud, OnPremise, or an empty string when the hosting model is unknown.</returns>
private static str resolveHosting(IApplicationEnvironment _env)
{
    Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.ICommonConfig common;
    HostingEnvironment he;

    if (!_env)
    {
        return '';
    }

    common = _env.get_Common();
    if (!common)
    {
        return '';
    }

    he = common.get_HostingEnvironment();
    if (he == HostingEnvironment::Cloud)
    {
        return #HostingCloud;
    }
    if (he == HostingEnvironment::OnPremises || he == HostingEnvironment::ServiceFabric)
    {
        return #HostingOnPrem;
    }

    // Fall back to the deployment type when the hosting environment is not conclusive
    if (common.get_DeploymentType() == Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.DeploymentType::Cloud)
    {
        return #HostingCloud;
    }
    if (common.get_DeploymentType() == Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.DeploymentType::OnPrem)
    {
        return #HostingOnPrem;
    }

    return '';
}

/// <summary>
/// Resolves the environment type reported to the feature service from the running environment.
/// Development environments (onebox, the compute emulator, and internal test) report an empty
/// value; any other environment with a Lifecycle Services environment id reports Prod. Sandbox
/// and production environments are not distinguished.
/// </summary>
/// <param name = "_env">The application environment of the running AOS.</param>
/// <returns>Prod for a production or sandbox environment; otherwise an empty string.</returns>
private static str resolveEnvironmentType(IApplicationEnvironment _env)
{
    Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.ICommonConfig common;
    Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.ILCSConfig lcs;

    if (!_env)
    {
        return '';
    }

    common = _env.get_Common();
    if (common)
    {
        // Local development environments are never production
        if (common.get_IsOneboxEnvironment()
            || common.get_HostingEnvironment() == HostingEnvironment::ComputeEmulator)
        {
            return '';
        }

        // Internal test environments are not customer production
        if (common.get_DeploymentEnvironmentType() == Microsoft.Dynamics.ApplicationPlatform.Environment.Settings.EnvironmentType::InternalTest)
        {
            return '';
        }
    }

    // Cloud environments registered in Lifecycle Services carry an environment id
    lcs = _env.get_LCS();
    if (lcs && lcs.get_LCSEnvironmentId() != '')
    {
        return #EnvProd;
    }

    return '';
}

/// <summary>
/// Enqueues a single run of the feature ensure on the batch server so the caller is never blocked.
/// </summary>
public static void runOnceInBackground()
{
    BatchHeader header;
    AAXWarehouseToolsFeatureEnsure task;

    task = AAXWarehouseToolsFeatureEnsure::construct();

    // Execute the batch task as the admin user
    header = BatchHeader::construct();
    header.parmExecutingBy('admin');
    header.addTask(task);
    header.save();
}

/// <summary>
/// Runs the feature ensure as a batch task.
/// </summary>
public void run()
{
    super();
    AAXWarehouseToolsFeatureEnsure::ensureFeature();
}

/// <summary>
/// Constructs a new instance of the <c>AAXWarehouseToolsFeatureEnsure</c> class.
/// </summary>
/// <returns>A new <c>AAXWarehouseToolsFeatureEnsure</c> instance.</returns>
public static AAXWarehouseToolsFeatureEnsure construct()
{
    return new AAXWarehouseToolsFeatureEnsure();
}

/// <summary>
/// Indicates whether the class can run as a batch task.
/// </summary>
/// <returns>True, indicating the feature ensure can run in batch.</returns>
public boolean canGoBatch()
{
    return true;
}

/// <summary>
/// Serializes the class state into a container.
/// </summary>
/// <returns>A container holding the serialized state.</returns>
public container pack()
{
    return [#CurrentVersion];
}

/// <summary>
/// Deserializes the class state from a container.
/// </summary>
/// <param name = "_packedClass">A container holding the serialized state.</param>
/// <returns>True if the container version is supported.</returns>
public boolean unpack(container _packedClass)
{
    int version = conpeek(_packedClass, 1);

    return version == #CurrentVersion;
}

/// <summary>
/// Provides a description for the batch task.
/// </summary>
/// <returns>A string description of the batch task.</returns>
public static ClassDescription description()
{
    return "AAXWarehouseTools feature ensure";
}
